'use strict';
const paths={pin:'M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',compass:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M16 8l-3 5-5 3 3-5Z',map:'M9 3l6 4 7-4v17l-7 3-6-4-7 3V5Z M9 3v16 M15 7v16',calendar:'M4 5h16v16H4Z M4 10h16 M8 2v6 M16 2v6',sun:'M12 3V1 M12 23v-2 M3 12H1 M23 12h-2 M5 5 3 3 M21 21l-2-2 M5 19l-2 2 M21 3l-2 2 M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0',ticket:'M3 6h18v4a2 2 0 0 0 0 4v4H3v-4a2 2 0 0 0 0-4Z M15 6v3 M15 11v2 M15 15v3',filter:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6',share:'M12 16V2 M7 7l5-5 5 5 M5 12H3v10h18V12h-2',arrow:'M5 12h14 M13 6l6 6-6 6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.compass}"/></svg>`;
const types=['展覽','市集','音樂表演','藝文','戶外','親子','美食','節慶'];
const cities=['全台灣','台北市','新北市','桃園市','台中市','台南市','高雄市','基隆市','新竹市','嘉義市','新竹縣','苗栗縣','彰化縣','南投縣','雲林縣','嘉義縣','屏東縣','宜蘭縣','花蓮縣','台東縣','澎湖縣','金門縣','連江縣'];
const photo=(id,w=900)=>`https://images.unsplash.com/${id}?auto=format&fit=crop&w=${w}&q=85`;
const events=window.ACTIVITIES;
let saved=[];try{saved=JSON.parse(localStorage.getItem('island-days-real-saved-v1')||'[]');if(!Array.isArray(saved))saved=[];saved=saved.filter(id=>events.some(e=>e.id===id));}catch{}
let state={tab:'explore',browse:false,q:'',city:'全台灣',start:'',end:'',types:[],fee:'all',sort:'soon',scenario:'normal',mapMode:'map',position:null,selected:null};
const CHECKED='2026/11/13';
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Taipei'}).format(new Date());
const iso=d=>d.toISOString().slice(0,10);
function weekend(){let d=new Date(today()+'T12:00:00Z'),n=d.getUTCDay();d.setUTCDate(d.getUTCDate()+(n===0?-1:6-n));const a=iso(d);d.setUTCDate(d.getUTCDate()+1);return[a,iso(d)];}
function available(e,start,end){let a=start||today(),b=end||'9999-12-31';a=[a,e.start].sort().at(-1);b=[b,e.end].sort()[0];if(a>b)return false;if(!e.closedDays)return true;let d=new Date(a+'T12:00:00Z');for(let n=0;n<7&&iso(d)<=b;n++,d.setUTCDate(d.getUTCDate()+1))if(!e.closedDays.includes(d.getUTCDay()))return true;return false;}
function sourceLinks(e){return [{name:e.sourceName,url:e.sourceUrl},...(e.references||[])].map(r=>'<a class="source-link" href="'+esc(r.url)+'" target="_blank" rel="noopener noreferrer">'+esc(r.name)+' ↗</a>').join('');}
let map=null,toastTimer,loadingTimer,returnFocus;const main=document.querySelector('#main');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateLabel=e=>{const crossYear=e.start.slice(0,4)!==e.end.slice(0,4);const show=d=>(crossYear?d:d.slice(5)).replaceAll('-','/');return show(e.start)+(e.start===e.end?'':' — '+show(e.end));};
function distance(e){if(!state.position||e.lat===null)return Infinity;let a=(e.lat-state.position.lat)*Math.PI/180,b=(e.lon-state.position.lon)*Math.PI/180;return 6371*2*Math.asin(Math.sqrt(Math.sin(a/2)**2+Math.cos(e.lat*Math.PI/180)*Math.cos(state.position.lat*Math.PI/180)*Math.sin(b/2)**2));}
function matches(e,s=state){const q=s.q.trim().replace(/臺/g,'台').toLowerCase();return(!q||[e.title,e.venue,e.city,e.address,e.desc,...e.types].join(' ').replace(/臺/g,'台').toLowerCase().includes(q))&&(s.city==='全台灣'||e.city===s.city)&&available(e,s.start,s.end)&&(!s.types.length||s.types.some(t=>e.types.includes(t)))&&(s.fee==='all'||(s.fee==='free'?e.fee===0:e.fee>0));}
function results(){let arr=events.filter(e=>matches(e));if(state.tab==='saved')arr=events.filter(e=>saved.includes(e.id));if(state.scenario==='empty')return[];return arr.sort((a,b)=>state.sort==='distance'&&state.position?distance(a)-distance(b):a.start.localeCompare(b.start)||a.id-b.id);}
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3200);}
function hydrateIcons(){document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function saveButton(e){return `<button class="save-button ${saved.includes(e.id)?'saved':''}" data-save="${e.id}" aria-label="${saved.includes(e.id)?'取消收藏':'收藏'}${e.title}" aria-pressed="${saved.includes(e.id)}">${icon('heart')}</button>`;}
function status(e){return e.status==='cancelled'?'已取消':e.status==='postponed'?'已延期・日期待公布':e.end<today()?'已結束':'';}
function card(e){return `<article class="card"><div class="card-cover"><a href="#event-${e.id}" data-detail="${e.id}" aria-label="查看${e.title}"><img src="${photo(e.image)}" alt="主題情境圖片，非活動現場：${e.types[0]}" loading="lazy"></a><span class="badge">${esc(e.label)}</span>${saveButton(e)}</div><div class="card-meta"><span class="type">${e.types.join(' / ')}</span><span>${dateLabel(e)}</span></div><h3><a href="#event-${e.id}" data-detail="${e.id}">${e.title}</a></h3><p class="card-location">${icon('pin')}${e.city}・${e.venue}</p><div class="card-bottom"><strong class="${e.status?'status-label':''}">${status(e)||e.price}</strong><span>${state.position&&e.lat!==null?`場館直線約 ${distance(e).toFixed(1)} 公里`:'查核 '+CHECKED}</span></div><div class="card-source">${sourceLinks({...e,references:[]})}</div></article>`;}
function mini(e){return `<a class="mini-card ${state.selected===e.id?'active':''}" href="#event-${e.id}" data-detail="${e.id}"><img src="${photo(e.image,300)}" alt="活動情境示意" loading="lazy"><div><small class="ending">${status(e)||`${dateLabel(e)} · 官方資訊`}</small><h3>${e.title}</h3><small>${e.city} · ${e.price}</small></div></a>`;}
function searchForm(){return `<form class="search-form" role="search">${icon('search')}<input type="search" aria-label="搜尋活動、地點或關鍵字" placeholder="搜尋活動、地點或關鍵字" value="${esc(state.q)}"><button type="submit" aria-label="搜尋">${icon('arrow')}</button></form>`;}
function filterButton(){return `<button class="filter-button" data-filter>${icon('filter')} 篩選${filterCount()?` (${filterCount()})`:''}</button>`;}
function filterCount(){return(state.city!=='全台灣'?1:0)+(state.start||state.end?1:0)+state.types.length+(state.fee!=='all'?1:0);}
function chips(){let a=[];if(state.city!=='全台灣')a.push(['city',state.city]);if(state.start||state.end)a.push(['date',`${state.start||'不限'} — ${state.end||'不限'}`]);state.types.forEach(t=>a.push(['type:'+t,t]));if(state.fee!=='all')a.push(['fee',state.fee==='free'?'免費活動':'付費活動']);if(state.q)a.push(['q',`搜尋：${state.q}`]);return a.length?`<div class="active-filters">${a.map(([k,v])=>`<button data-remove="${esc(k)}" aria-label="移除${esc(v)}">${esc(v)} ×</button>`).join('')}<button data-reset>清除全部</button></div>`:'';}
function empty(savedPage=false){return `<div class="empty"><span>${icon(savedPage?'heart':'compass')}</span><h2>${savedPage&&!saved.length?'把喜歡的日子，先收藏起來':'這次還沒找到剛好的活動'}</h2><p>${savedPage&&!saved.length?'看到心動的活動，點一下愛心，下次就能在這裡找到。':'試試其他日期、清除篩選，或看看鄰近縣市。目前僅收錄人工查核的活動，未完整涵蓋全台。'}</p><button class="primary" ${savedPage&&!saved.length?'data-tab="explore"':'data-reset'}>${savedPage&&!saved.length?'去探索活動':'清除篩選，重新探索'} ↗</button></div>`;}
function statePanel(){if(state.scenario==='loading')return `<div class="grid" aria-label="活動載入中" aria-busy="true">${Array(3).fill('<div class="skeleton"></div>').join('')}</div>`;if(state.scenario==='error')return `<div class="empty"><span>⌁</span><h2>網路好像打了個小盹</h2><p>這是網路錯誤的原型示範，請點重試回到活動。</p><button class="primary" data-retry>重新載入 ↻</button></div>`;return '';}
function render(){if(map){map.remove();map=null;}clearTimeout(loadingTimer);document.querySelector('#city-label').textContent=state.city;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===state.tab));document.querySelectorAll('.saved-count').forEach(e=>e.textContent=saved.length);if(state.tab==='map')renderMap();else if(state.tab==='saved')renderSaved();else renderExplore();hydrateIcons();main.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{img.style.opacity='.15';img.alt='圖片未能載入，活動資訊仍可閱讀';},{once:true}));if(state.scenario==='loading')loadingTimer=setTimeout(()=>{if(state.scenario==='loading'){state.scenario='normal';render();}},1800);}
function renderExplore(){const filtered=!!(state.browse||state.q||filterCount()),list=results();main.innerHTML=`${filtered?'<div class="page-top"><span class="eyebrow">FIND YOUR LITTLE ADVENTURE</span><h1>下一站，去哪裡？</h1><p>真實活動，附上可查證的官方來源。</p></div><div class="toolbar">'+searchForm()+filterButton()+'</div>':'<section class="hero"><div class="hero-copy"><div class="eyebrow">A LITTLE ESCAPE, A LOVELY DAY.</div><h1>給日常一點<br><span>出走的理由。</span></h1><p>一場展覽、一個市集，或一段沒有安排的午後。<br>在台灣，發現下一個喜歡的日子。</p>'+searchForm()+'</div><a class="hero-art" href="#event-101" data-detail="101"><img src="'+photo('photo-1455390582262-044cdead277a',1200)+'" alt="閱讀主題情境圖片，非活動現場"><div class="hero-stamp">WEEKEND<b>慢慢走</b>TAIWAN</div><div class="hero-caption"><small>真實活動 / 圖片為情境示意</small><p>紀州庵館慶，城南慢慢逛 ↗</p></div></a></section>'}
<div class="data-note">✓ 活動依官方或主辦資料人工整理 · 最後查核 ${CHECKED}<br><small>非即時同步；照片為情境示意，活動異動、名額與票價請再確認官方連結。</small></div>
<section class="quick-links" aria-label="快速找活動">${[['today','sun','今天','留一點時間給今天'],['weekend','calendar','本週末','週末值得好好過'],['free','ticket','免費活動','快樂不一定要花錢'],['near','pin','附近活動','美好就在不遠處']].map(([k,i,t,u])=>'<button class="quick" data-quick="'+k+'"><span class="quick-icon">'+icon(i)+'</span><span><strong>'+t+'</strong><small>'+u+'</small></span><span class="arrow">↗</span></button>').join('')}</section>
<section id="activities"><div class="section-heading"><div><h2>${filtered?'找到你的活動':'值得出門的好日子'}<span class="subtitle">CURATED FOR YOU</span></h2><p>${list.length} 個活動 · 有來源，才收錄</p></div>${filterButton()}</div><div class="types-row"><button class="pill ${!state.types.length?'active':''}" data-type="all">全部活動</button>${types.map(t=>'<button class="pill '+(state.types.includes(t)?'active':'')+'" data-type="'+t+'">'+t+'</button>').join('')}</div>${chips()}<div class="results-info"><span>台灣時間 ${today().replaceAll('-','/')} · 費用未確認不列為免費</span><select class="sort" aria-label="活動排序"><option value="soon">即將開始</option>${state.position?'<option value="distance">距離最近</option>':''}</select></div>${statePanel()||(list.length?'<div class="grid">'+list.map(card).join('')+'</div>':empty())}</section>
${!filtered&&state.scenario==='normal'?'<aside class="editor-note"><div><small>REAL EVENTS, SLOW DAYS</small><h3>把靈感，變成真的出發。</h3><p>點開每張卡片上的參考連結，確認資訊，再安排你的好日子。</p></div><span class="big-flower">✳</span></aside><section><div class="section-heading"><div><h2>即將結束</h2><p>依活動結束日期排序，僅顯示未來七天內的活動。</p></div></div><div class="mini-grid">'+events.filter(e=>e.end>=today()&&e.end<=iso(new Date(Date.parse(today()+'T12:00:00Z')+7*86400000))).sort((a,b)=>a.end.localeCompare(b.end)).slice(0,3).map(mini).join('')+'</div></section>':''}`;
const sort=main.querySelector('.sort');if(sort)sort.value=state.sort;}
function renderSaved(){let list=results();main.innerHTML=`<div class="page-top"><div class="eyebrow">YOUR NEXT GOOD DAY</div><h1>我的口袋清單<span style="font-size:16px;margin-left:12px">${saved.length}</span></h1><p>先留住心動，再挑個好日子出發。</p></div><div class="map-notice"><span>收藏儲存在此瀏覽器，清除網站資料後可能遺失；不需登入。</span>${icon('heart')}</div>${chips()}${statePanel()||(list.length?`<div class="section-heading"><h2>留給下一次出發</h2><button class="text-button" data-reset>清除搜尋與篩選</button></div><div class="grid">${list.sort((a,b)=>(b.status?1:0)-(a.status?1:0)).map(card).join('')}</div>`:empty(true))}`;}
function renderMap(){const list=results();main.innerHTML=`<div class="page-top"><span class="eyebrow">GOOD THINGS ARE CLOSER THAN YOU THINK</span><h1>跟著地圖，找點好玩的。</h1><p>真實活動與場館參考位置；詳細入口請查看官方資訊。</p></div><div class="toolbar">${searchForm()}${filterButton()}<div class="map-toggle"><button data-map-mode="map" class="${state.mapMode==='map'?'active':''}">地圖</button><button data-map-mode="list" class="${state.mapMode==='list'?'active':''}">清單</button></div></div>${chips()}<div class="map-notice"><span>${state.position?'本次位置僅供距離排序；地圖服務會依畫面範圍取得圖磚。':'尚未開啟定位，可手動選縣市。未核實座標的活動只列於清單。'}</span><button data-locate>${state.position?'重新定位':'開啟定位'}</button></div><div class="results-info"><span>${list.length} 個活動 · ${list.filter(e=>e.lat!==null).length} 個場館標記</span><span>查核 ${CHECKED}</span></div>${statePanel()||(!list.length?empty():state.mapMode==='list'?'<div class="grid">'+list.map(card).join('')+'</div>':'<div class="map-layout"><div class="map-canvas" id="map" aria-label="活動位置地圖"></div><div class="map-list">'+list.map(mini).join('')+'</div></div>')}`;if(list.length&&state.mapMode==='map'&&state.scenario==='normal')setTimeout(()=>initMap(list.filter(e=>e.lat!==null)),0);}
function initMap(list){let el=document.querySelector('#map');if(!el)return;if(!list.length){el.innerHTML='<div class="empty"><h2>這些活動尚未核實座標</h2><p>請切換清單查看官方地址，或用場地名稱導航。</p></div>';return;}if(!window.L){el.innerHTML=`<div class="fallback-map"><span>地圖服務未載入 · 以下為可點選的位置示意圖</span>${list.map((e,i)=>`<button class="fallback-pin" data-detail="${e.id}" style="left:${12+(i*29)%75}%;top:${12+(i*17)%68}%" aria-label="${e.title}">${i+1}</button>`).join('')}</div>`;return;}map=L.map(el,{scrollWheelZoom:false}).setView([23.8,121],7);const tiles=L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors'}).addTo(map);let tileErrors=0;tiles.on('tileerror',()=>{if(++tileErrors===3)toast('底圖載入失敗，仍可點選活動標記或切換清單');});list.forEach((e,i)=>L.marker([e.lat,e.lon],{icon:L.divIcon({className:'',html:`<div class="map-marker">${i+1}</div>`,iconSize:[36,36]})}).addTo(map).bindPopup(`<strong>${esc(e.title)}</strong><br>${e.city} · ${e.price}<br>場館位置供參考<br><button data-detail="${e.id}">查看活動詳情 ↗</button>`));const bounds=L.latLngBounds(list.map(e=>[e.lat,e.lon]));if(state.position){L.circleMarker([state.position.lat,state.position.lon],{radius:8,color:'#fff',fillColor:'#367bba',fillOpacity:1}).addTo(map).bindPopup('你的本次位置');}map.fitBounds(bounds,{padding:[40,40],maxZoom:13});}
function reset(){Object.assign(state,{q:'',city:'全台灣',start:'',end:'',types:[],fee:'all',scenario:'normal'});render();}
function openFilters(){const f=document.querySelector('#filter-form');f.city.value=state.city;f.start.value=state.start;f.end.value=state.end;f.querySelectorAll('[name=type]').forEach(i=>i.checked=state.types.includes(i.value));f.querySelector(`[name=fee][value=${state.fee}]`).checked=true;document.querySelector('#filter-error').textContent='';updateDatePreset();document.querySelector('#filter-dialog').showModal();}
function updateDatePreset(){const a=document.querySelector('#start-date').value,b=document.querySelector('#end-date').value;document.querySelectorAll('[data-period]').forEach(el=>el.classList.toggle('selected',el.dataset.period==='any'?!a&&!b:el.dataset.period==='today'?a===today()&&a===b:a===weekend()[0]&&b===weekend()[1]));}
function detail(id,hash=true){const e=events.find(e=>e.id===id);if(!e){toast('此活動連結已更新或下架，請重新探索。');return;}returnFocus=document.activeElement;state.selected=id;const d=document.querySelector('#detail-dialog');d.innerHTML=`<div class="detail-image"><img src="${photo(e.image,1200)}" alt="主題情境示意，非活動現場"><button class="icon-button close-dialog" aria-label="關閉活動詳情">←</button>${saveButton(e)}<span class="photo-disclaimer">情境圖片・非活動現場或官方海報</span></div><div class="detail-body"><div class="detail-kicker"><span>官方／主辦資訊</span>${e.types.join(' / ')}</div><h1>${e.title}</h1>${status(e)?'<div class="detail-state">'+status(e)+'</div>':''}<div class="detail-info">${icon('calendar')}<div><strong>${e.start.replaceAll('-','/')}${e.start===e.end?'':' — '+e.end.replaceAll('-','/')}</strong><small>${e.hours}</small></div>${icon('pin')}<div><strong>${e.city}・${e.venue}</strong><small>${e.address}</small></div>${icon('ticket')}<div><strong>${e.price}</strong><small>${e.booking?'需報名；剩餘名額請向主辦確認':'入場與預約規定請查看官方說明'}</small></div></div><h2>活動介紹</h2><p>${e.desc}</p><h2>出發前先看這裡</h2><p>${e.notes}</p><h2>主辦單位</h2><p>${e.organizer}</p><section class="official-sources"><h2>活動參考連結</h2><p>以下連結可直接開啟官方公告或主辦指定報名頁。</p>${sourceLinks(e)}</section><p class="source-line">本站最後查核：${CHECKED}（台灣時間）<br>這是人工整理的資料快照，並非官方即時串接；查核時間不代表主辦更新時間。<br>活動狀態：${status(e)||'依收錄公告安排；出發前請再確認異動'}。</p><p class="detail-disclaimer">照片為主題情境圖片，非活動現場。時間、費用、名額及天候異動，仍以主辦單位最新公告為準。</p></div><div class="detail-actions"><button class="secondary" data-share="${e.id}" aria-label="分享此活動">${icon('share')}分享</button><a class="secondary" href="https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(e.venue+' '+e.address)}" target="_blank" rel="noopener noreferrer">${icon('pin')}導航</a><a class="primary" href="${esc(e.bookingUrl||e.sourceUrl)}" target="_blank" rel="noopener noreferrer">${e.booking?'查看報名／購票':'查看官方活動'} ↗</a></div>`;if(!d.open)d.showModal();d.scrollTop=0;if(hash)history.pushState(null,'',`#event-${id}`);}
function closeDetail(){const d=document.querySelector('#detail-dialog');if(d.open)d.close();if(location.hash.startsWith('#event-'))history.replaceState(null,'',location.pathname+location.search);returnFocus?.focus?.();}
document.querySelector('#city').innerHTML=cities.map(c=>`<option>${c}</option>`).join('');document.querySelector('#type-options').innerHTML=types.map(t=>`<label><input type="checkbox" name="type" value="${t}"><span>${t}</span></label>`).join('');
document.addEventListener('click',async ev=>{const b=ev.target.closest('button,a');if(!b)return;
 if(b.dataset.tab){ev.preventDefault();state.tab=b.dataset.tab;render();window.scrollTo({top:0});}
 if(b.matches('.brand')){ev.preventDefault();state.tab='explore';reset();window.scrollTo({top:0});}
 if(b.dataset.save){const id=Number(b.dataset.save);if(saved.includes(id))saved=saved.filter(x=>x!==id);else saved.push(id);try{localStorage.setItem('island-days-real-saved-v1',JSON.stringify(saved));toast(saved.includes(id)?'已收藏，留給下一個好日子 ♡':'已取消收藏');}catch{toast('此瀏覽器無法儲存，收藏僅保留至關閉頁面');}const scroll=window.scrollY;render();window.scrollTo({top:scroll});document.querySelectorAll(`[data-save="${id}"]`).forEach(el=>{el.outerHTML=saveButton(events.find(e=>e.id===id));});}
 if(b.dataset.detail){ev.preventDefault();detail(Number(b.dataset.detail));}
 if(b.hasAttribute('data-filter')||b.id==='city-button')openFilters();
 if(b.hasAttribute('data-reset'))reset();
 if(b.dataset.type){state.types=b.dataset.type==='all'?[]:[b.dataset.type];render();}
 if(b.dataset.remove){const k=b.dataset.remove;if(k==='city')state.city='全台灣';if(k==='date'){state.start='';state.end='';}if(k==='fee')state.fee='all';if(k==='q')state.q='';if(k.startsWith('type:'))state.types=state.types.filter(t=>t!==k.slice(5));render();}
 if(b.dataset.quick){const q=b.dataset.quick;if(q==='near'){document.querySelector('#location-message').textContent='也可以手動選擇縣市，不需開啟定位。';document.querySelector('#location-dialog').showModal();}else{state.tab='explore';if(q==='today'){state.start=today();state.end=today();}if(q==='weekend'){[state.start,state.end]=weekend();}if(q==='free')state.fee=state.fee==='free'?'all':'free';render();document.querySelector('#activities')?.scrollIntoView({behavior:'smooth',block:'start'});}}
 if(b.dataset.period){const q=b.dataset.period;document.querySelector('#start-date').value=q==='today'?today():q==='weekend'?weekend()[0]:'';document.querySelector('#end-date').value=q==='today'?today():q==='weekend'?weekend()[1]:'';updateDatePreset();}
 if(b.matches('.close-dialog')){const d=b.closest('dialog');if(d.id==='detail-dialog')closeDetail();else d.close();}
 if(b.id==='clear-filters'){document.querySelector('#filter-form').reset();document.querySelector('#city').value='全台灣';updateDatePreset();}
 if(b.hasAttribute('data-show-all')){state.browse=true;render();document.querySelector('#activities')?.scrollIntoView();}
 if(b.hasAttribute('data-ending')){state.start='2026-11-13';state.end='2026-11-15';state.q='';render();document.querySelector('#activities')?.scrollIntoView();}
 if(b.dataset.mapMode){state.mapMode=b.dataset.mapMode;render();}
 if(b.hasAttribute('data-locate'))document.querySelector('#location-dialog').showModal();
 if(b.id==='manual-location'){document.querySelector('#location-dialog').close();openFilters();}
 if(b.id==='allow-location'){const msg=document.querySelector('#location-message');if(!navigator.geolocation){msg.textContent='這個瀏覽器不支援定位，請手動選擇縣市。';return;}b.disabled=true;msg.textContent='正在取得你的位置…';navigator.geolocation.getCurrentPosition(p=>{b.disabled=false;state.position={lat:p.coords.latitude,lon:p.coords.longitude};state.tab='map';state.city='全台灣';state.sort='distance';document.querySelector('#location-dialog').close();render();toast('已取得本次位置；地圖顯示場館參考位置');},()=>{b.disabled=false;msg.textContent='未取得定位同意或位置暫時無法取得。你仍可手動選縣市，不影響探索。';},{timeout:10000,maximumAge:60000});}
 if(b.dataset.share){const e=events.find(e=>e.id===Number(b.dataset.share)),url=location.href.split('#')[0]+'#event-'+e.id,data={title:e.title,text:e.title+'｜'+e.sourceName+'：'+e.sourceUrl,url};try{if(navigator.share)await navigator.share(data);else if(navigator.clipboard){await navigator.clipboard.writeText(data.title+'\n'+data.text+'\n'+url);toast('已複製活動與官方參考連結');}else{toast('分享連結：'+url);}}catch(err){if(err.name!=='AbortError')toast('分享未完成，請複製網址列的活動連結。');}}
 if(b.hasAttribute('data-retry')){state.scenario='loading';render();}
});
document.addEventListener('submit',ev=>{if(ev.target.matches('.search-form')){ev.preventDefault();state.q=ev.target.querySelector('input').value;state.scenario='normal';render();}if(ev.target.id==='filter-form'){ev.preventDefault();const f=ev.target;if(f.start.value&&f.end.value&&f.end.value<f.start.value){document.querySelector('#filter-error').textContent='結束日期不能早於開始日期。';return;}state.city=f.city.value;state.start=f.start.value;state.end=f.end.value;state.types=[...f.querySelectorAll('[name=type]:checked')].map(i=>i.value);state.fee=f.querySelector('[name=fee]:checked').value;document.querySelector('#filter-dialog').close();render();}});
document.addEventListener('change',ev=>{if(ev.target.matches('.sort')){state.sort=ev.target.value;render();}if(ev.target.id==='scenario'){state.scenario=ev.target.value;render();}if(ev.target.matches('input[type=date]'))updateDatePreset();});
document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom){if(d.id==='detail-dialog')closeDetail();else d.close();}}});});
document.querySelector('#detail-dialog').addEventListener('cancel',e=>{e.preventDefault();closeDetail();});window.addEventListener('popstate',()=>{const id=location.hash.match(/^#event-(\d+)$/);if(id)detail(Number(id[1]),false);else closeDetail();});window.addEventListener('offline',()=>toast('目前離線；已載入活動可繼續閱讀，地圖與圖片可能無法載入。'));
render();const deep=location.hash.match(/^#event-(\d+)$/);if(deep)detail(Number(deep[1]),false);

